insert into species (id, name, class, class_scope, size, diet, description, notes, source_ids, confidence) values
  ('night_fury', 'Night Fury', 'Strike', 'franchise', 'medium', null, 'A sleek black dragon so fast and so rarely seen that Vikings had no record of what it looked like. It fires concentrated blasts and disappears against the night sky.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'high'),
  ('light_fury', 'Light Fury', 'Strike', 'franchise', 'medium', null, 'A pale relative of the Night Fury that can almost vanish from sight by flying through its own fire. Wild and very wary of people.', 'Description is a draft; review before publishing.', array['wiki_httyd3', 'claude_knowledge', 'repo_romainchamb', 'repo_uokik']::text[], 'high'),
  ('night_light', 'Night Light', 'Strike', 'franchise', 'small', null, 'The hatchlings of a Night Fury and a Light Fury, seen at the very end of the third film.', 'Description is a draft; review before publishing.', array['wiki_httyd3', 'claude_knowledge', 'repo_uokik']::text[], 'high'),
  ('deadly_nadder', 'Deadly Nadder', 'Tracker', 'franchise', 'medium', null, 'A colourful, bird-like dragon with a crown of horns and a tail that fires spines. Quick on its feet and proud of its looks.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'high'),
  ('gronckle', 'Gronckle', 'Boulder', 'franchise', 'medium', null, 'A round, heavy dragon whose small wings beat fast like a bumblebee''s. Slow to anger and much tougher than it looks.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'high'),
  ('hideous_zippleback', 'Hideous Zippleback', 'Mystery', 'franchise', 'large', null, 'A two-headed dragon: one head breathes out gas and the other lights it, so both heads have to cooperate.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'high'),
  ('monstrous_nightmare', 'Monstrous Nightmare', 'Stoker', 'franchise', 'large', null, 'A big, hot-tempered dragon that can set its own body on fire. Fierce, loud and hard to handle.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'high'),
  ('terrible_terror', 'Terrible Terror', 'Stoker', 'franchise', 'tiny', null, 'A cat-sized dragon that turns up in groups and squabbles over food.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'high'),
  ('red_death', 'Red Death', 'Stoker', 'franchise', 'titan', null, 'A gigantic dragon that ruled the dragons'' nest and forced smaller dragons to bring it food.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'high'),
  ('boneknapper', 'Boneknapper', 'Mystery', 'franchise', null, null, 'A dragon that wears the bones of others as armour. One of the entries in Berk''s Book of Dragons.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'repo_uokik']::text[], 'medium'),
  ('changewing', 'Changewing', 'Mystery', 'franchise', null, null, 'A dragon that changes colour to blend into its surroundings. One of the entries in Berk''s Book of Dragons.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'wiki_httyd2', 'repo_uokik']::text[], 'medium'),
  ('scauldron', 'Scauldron', 'Tidal', 'franchise', null, null, 'A sea dragon that sprays scalding water instead of fire. One of the entries in Berk''s Book of Dragons.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'medium'),
  ('skrill', 'Skrill', 'Strike', 'franchise', null, null, 'A dragon associated with lightning. One of the entries in Berk''s Book of Dragons.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'medium'),
  ('thunderdrum', 'Thunderdrum', 'Tidal', 'franchise', null, null, 'A sea dragon whose roar is loud enough to stun. One of the entries in Berk''s Book of Dragons.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'wiki_httyd2', 'repo_romainchamb', 'repo_uokik']::text[], 'medium'),
  ('timberjack', 'Timberjack', 'Sharp', 'franchise', null, null, 'A dragon with huge, blade-like wings that can slice through trees. One of the entries in Berk''s Book of Dragons.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'wiki_httyd2', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'medium'),
  ('whispering_death', 'Whispering Death', 'Boulder', 'franchise', null, null, 'A burrowing dragon with rings of teeth that tunnels through rock. One of the entries in Berk''s Book of Dragons.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'wiki_httyd2', 'repo_romainchamb', 'repo_uokik']::text[], 'medium'),
  ('smothering_smokebreath', 'Smothering Smokebreath', 'Mystery', 'franchise', 'small', null, 'A small dragon that hides inside clouds of smoke it makes itself.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'wiki_httyd3', 'repo_uokik']::text[], 'medium'),
  ('snaptrapper', 'Snaptrapper', 'Mystery', 'franchise', null, null, 'A many-headed dragon whose jaws open like petals to lure prey in.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'wiki_httyd2', 'repo_romainchamb', 'repo_uokik']::text[], 'medium'),
  ('speed_stinger', 'Speed Stinger', 'Sharp', 'franchise', 'small', null, 'A small, flightless dragon that runs very fast and can paralyse with its sting.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'repo_uokik']::text[], 'medium'),
  ('grapple_grounder', 'Grapple Grounder', null, null, null, null, '', 'No description yet.', array['wiki_httyd1']::text[], 'low'),
  ('stormcutter', 'Stormcutter', 'Sharp', 'franchise', 'large', null, 'A large dragon with four wings that can spread into an X, and an owl-like face.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'claude_knowledge', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'high'),
  ('rumblehorn', 'Rumblehorn', 'Tracker', 'franchise', 'large', null, 'A heavy dragon with a hammer-shaped snout and a strong sense of smell, good at tracking.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'claude_knowledge', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'high'),
  ('hotburple', 'Hotburple', 'Boulder', 'franchise', 'medium', null, 'A heavy, sleepy cousin of the Gronckle that swallows rocks and spits out lava.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'claude_knowledge', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'high'),
  ('bewilderbeast', 'Bewilderbeast', 'Tidal', 'franchise', 'titan', null, 'A colossal, tusked alpha dragon that breathes ice and can command other dragons.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'claude_knowledge', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'high'),
  ('scuttleclaw', 'Scuttleclaw', 'Sharp', 'franchise', 'small', null, 'A small, lively dragon; young ones appear in the second and third films.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'medium'),
  ('seashocker', 'Seashocker', 'Tidal', 'franchise', null, null, 'A sea dragon that can give off electric shocks.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'medium'),
  ('firefang', 'Firefang', null, null, null, null, '', 'No description yet.', array['wiki_httyd2', 'wiki_httyd3']::text[], 'low'),
  ('hobblegrunt', 'Hobblegrunt', 'Stoker', 'franchise', null, null, 'A dragon whose colours change with its mood.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'low'),
  ('horrible_hornswoggler', 'Horrible Hornswoggler', null, null, null, null, '', 'No description yet.', array['wiki_httyd2', 'wiki_httyd3']::text[], 'low'),
  ('raincutter', 'Raincutter', 'Sharp', 'franchise', null, null, 'A spiky-framed dragon that prefers rain and grey skies.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'low'),
  ('shovelhelm', 'Shovelhelm', 'Boulder', 'franchise', null, null, 'A dragon with a broad, shovel-shaped head.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'low'),
  ('snafflefang', 'Snafflefang', 'Boulder', 'franchise', null, null, 'A sharp-toothed dragon that likes to gnaw on rocks.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'medium'),
  ('snifflehunch', 'Snifflehunch', 'Tracker', 'franchise', null, null, 'A curious dragon with a keen nose that sniffs out friend or foe.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'low'),
  ('stubcrown_stinker', 'Stubcrown Stinker', null, null, null, null, '', 'No description yet.', array['wiki_httyd2', 'wiki_httyd3']::text[], 'low'),
  ('thornridge', 'Thornridge', null, null, null, null, '', 'No description yet.', array['wiki_httyd2', 'wiki_httyd3']::text[], 'low'),
  ('threadtail', 'Threadtail', 'Stoker', 'franchise', null, null, 'A long, slender dragon with a thin, whip-like tail.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'low'),
  ('thunderclaw', 'Thunderclaw', 'Tracker', 'franchise', null, null, '', 'No description yet.', array['wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'low'),
  ('windgnasher', 'Windgnasher', 'Tracker', 'franchise', null, null, 'A hump-backed dragon that can catch a scent carried on the wind.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'low'),
  ('windstriker', 'Windstriker', 'Sharp', 'franchise', null, null, 'A dragon that blasts super-heated air instead of flame.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'low'),
  ('sliquifier', 'Sliquifier', null, null, null, null, '', 'No description yet.', array['wiki_httyd2']::text[], 'medium'),
  ('songwing', 'Songwing', 'Strike', 'franchise', null, null, 'A dragon with a small body and very large wings.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'repo_uokik']::text[], 'medium'),
  ('submaripper', 'Submaripper', 'Tidal', 'franchise', null, null, 'A huge sea dragon said to drag ships under with whirlpools.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_httyd3', 'repo_uokik']::text[], 'medium'),
  ('typhoomerang', 'Typhoomerang', 'Stoker', 'franchise', null, null, 'A dragon that spins as it flies, leaving a spiral of fire behind it.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'repo_uokik']::text[], 'medium'),
  ('deathgripper', 'Deathgripper', 'Strike', 'franchise', 'large', null, 'A spiky, aggressive dragon with a venomous, pincer-like tail. The dragon hunter Grimmel uses them as his attack pack.', 'Description is a draft; review before publishing.', array['wiki_httyd3', 'claude_knowledge', 'repo_uokik']::text[], 'high'),
  ('crimson_goregutter', 'Crimson Goregutter', 'Boulder', 'franchise', 'large', null, 'A large, antlered dragon that looks fierce but mostly wants to be left alone.', 'Description is a draft; review before publishing.', array['wiki_httyd3', 'repo_uokik']::text[], 'medium'),
  ('hobgobbler', 'Hobgobbler', 'Mystery', 'franchise', 'small', null, 'A small, round dragon that many Vikings believe brings bad luck.', 'Description is a draft; review before publishing.', array['wiki_httyd3', 'repo_uokik']::text[], 'medium'),
  ('fireworm', 'Fireworm', 'Stoker', 'franchise', 'tiny', null, 'A tiny dragon whose body burns so hot that it glows.', 'Description is a draft; review before publishing.', array['wiki_httyd3', 'repo_uokik']::text[], 'low'),
  ('buffalord', 'Buffalord', 'Mystery', 'franchise', null, null, 'A huge, bison-like dragon.', 'Description is a draft; review before publishing.', array['wiki_httyd3', 'repo_uokik']::text[], 'medium'),
  ('dramillion', 'Dramillion', 'Mystery', 'franchise', null, null, 'A dragon that imitates the fire of other dragons.', 'Description is a draft; review before publishing.', array['wiki_httyd3', 'repo_romainchamb', 'repo_uokik']::text[], 'medium'),
  ('singetail', 'Singetail', 'Stoker', 'franchise', null, null, 'A territorial dragon that can shoot fire from its mouth, gills and tail.', 'Description is a draft; review before publishing.', array['wiki_httyd3', 'repo_uokik']::text[], 'medium');
insert into individuals (id, name, species_id, description, notes, source_ids, confidence) values
  ('toothless', 'Toothless', 'night_fury', 'Hiccup''s Night Fury. Loses half of his tail fin, can only fly with Hiccup''s help, becomes his closest friend and later the alpha of all dragons.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3']::text[], 'high'),
  ('stormfly', 'Stormfly', 'deadly_nadder', 'Astrid''s Deadly Nadder. Quick, loyal and competitive.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3']::text[], 'high'),
  ('meatlug', 'Meatlug', 'gronckle', 'Fishlegs''s Gronckle. Gentle and affectionate.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3']::text[], 'high'),
  ('hookfang', 'Hookfang', 'monstrous_nightmare', 'Snotlout''s Monstrous Nightmare. Stubborn, and often ignores his rider.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3']::text[], 'high'),
  ('barf_and_belch', 'Barf & Belch', 'hideous_zippleback', 'The Zippleback ridden by the twins Ruffnut and Tuffnut, one twin per head.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3']::text[], 'high'),
  ('the_red_death', 'The Red Death', 'red_death', 'The giant queen of the dragons'' nest, defeated by Hiccup and Toothless at the end of the first film.', 'Description is a draft; review before publishing.', array['wiki_httyd1', 'claude_knowledge', 'wiki_httyd2', 'wiki_httyd3']::text[], 'high'),
  ('cloudjumper', 'Cloudjumper', 'stormcutter', 'Valka''s Stormcutter, who carried her away from Berk years before the second film.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'claude_knowledge', 'wiki_httyd3']::text[], 'high'),
  ('skullcrusher', 'Skullcrusher', 'rumblehorn', 'A Rumblehorn ridden by Stoick in the second film and by Eret in the third.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'claude_knowledge', 'wiki_httyd3']::text[], 'high'),
  ('grump', 'Grump', 'hotburple', 'Gobber''s sleepy Hotburple.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'claude_knowledge', 'wiki_httyd3']::text[], 'high'),
  ('valkas_bewilderbeast', 'Valka''s Bewilderbeast', 'bewilderbeast', 'The alpha that sheltered the dragons of Valka''s ice sanctuary.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'claude_knowledge']::text[], 'high'),
  ('dragos_bewilderbeast', 'Drago''s Bewilderbeast', 'bewilderbeast', 'The alpha controlled by Drago Bludvist, used to take command of other dragons.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'claude_knowledge', 'wiki_httyd3']::text[], 'high'),
  ('the_light_fury', 'The Light Fury', 'light_fury', 'A wild Light Fury who becomes Toothless''s mate.', 'Description is a draft; review before publishing.', array['wiki_httyd3', 'claude_knowledge']::text[], 'high'),
  ('night_lights', 'The Night Lights', 'night_light', 'Toothless and the Light Fury''s three hatchlings, seen at the end of the third film.', 'One entry for all three. The wiki names them Dart, Pouncer and Ruffrunner; those names come from outside the films. Description is a draft; review before publishing.', array['wiki_httyd3', 'claude_knowledge']::text[], 'high'),
  ('gothis_pet', 'Gothi''s Pet', 'terrible_terror', 'Gothi''s Terrible Terror.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_httyd3', 'wiki_dragon_pages']::text[], 'low'),
  ('gruff', 'Gruff', 'hobblegrunt', 'A blind Hobblegrunt rescued by Valka.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_dragon_pages']::text[], 'low'),
  ('thump', 'Thump', 'raincutter', 'One of the dragons living in Valka''s sanctuary.', 'Description is a draft; review before publishing.', array['wiki_httyd2', 'wiki_dragon_pages']::text[], 'low'),
